          next++;
        }
      }
      else if (code !== Character.LineFeed) {
        continue;
      }
      fields[field] = start;
      fields[field | 1] = cursor;
      fields[field | 2] = next;
      fields[field | 3] = 0;
      field = (field + 4) & 0x7FFFFFFF;
      start = next;
    }
    if (start < limit) {
      fields[field] = start;
      fields[field | 1] = limit;
      fields[field | 2] = limit;
      fields[field | 3] = 0;
      field = (field + 4) & 0x7FFFFFFF;
    }

