class Index0 {
  static scan(source: string, fields: Int32Array): ScanningResult {
    let field = 0;
    let start = 0;
    let lf = source.indexOf("\n");
    let cr = source.indexOf("\r");
    const normalized = cr < 0;
    const limit = source.length;

    while (start < limit) {
      let end = lf;
      let next = end + 1;
