import type { Buffer } from "node:buffer";
import { Character } from "../constants/character.ts";
import type { SourceLocation, SourceLocator, SourcePosition } from "../source-view.ts";

const enum BlockLineField {
  Start,
  End,
  Next,
  State,
  Stride,
}

const enum BlockLineState {
  Lazy = 1,
}

const enum BlockLineCapacity {
  Initial = 4,
  DoublingLimit = 16,
}

export const enum IndentedLine {
  Underindented = -1,
  Blank,
  Appended,
}

interface ScanningResult {
  fields: Int32Array;
  length: number;
  normalized: boolean;
}

// Typical Markdown lines exceed 16 characters; cap the hint at 16,384 lines.
function getLineCapacity(sourceLength: number): number {
  return Math.min((sourceLength + 15) >>> 4, 16384);
}

function growLineFields(fields: Int32Array, fieldLength: number): Int32Array {
  if (fieldLength <= fields.length) {
    return fields;
  }
  let capacity = fields.length / BlockLineField.Stride;
  while (capacity < fieldLength / BlockLineField.Stride) {
    capacity += capacity < BlockLineCapacity.DoublingLimit
      ? Math.max(BlockLineCapacity.Initial, capacity)
      : capacity >>> 1;
  }
  const next = new Int32Array(capacity * BlockLineField.Stride);
  next.set(fields);
  return next;
}

class Latin1 {
  static positions = new Uint32Array(256);
  static {
    for (let mask = 1; mask < this.positions.length; mask++) {
      const rest = mask & (mask - 1);
      this.positions[mask] = (this.positions[rest] << 3) | (~Math.clz32(mask ^ rest) & 7);
    }
  }

  static minimum = 2048;
  static scratchBytes: Buffer | undefined;
  static scratchWords: Uint32Array | undefined;
  static scratchLimit = 0;

  // eslint-disable-next-line node/prefer-global/buffer
  static alloc = globalThis.Buffer?.allocUnsafeSlow;

  static scan(source: string, fields: Int32Array): ScanningResult {
    const limit = source.length;
    if (this.scratchLimit < limit) {
      const bytes = this.alloc(limit);
      this.scratchBytes = bytes;
      this.scratchWords = new Uint32Array(bytes.buffer, bytes.byteOffset, limit >>> 2);
      this.scratchLimit = limit;
    }

    const bytes = this.scratchBytes!;
    const words = this.scratchWords!;
    bytes.write(source, 0, limit, "latin1");
    let field = 0;
    let start = 0;
    let cursor = 0;
    // The offset after the last CR also identifies its optional LF.
    let lastCR = -1;
    const positions = this.positions;
    const wordLimit = limit & ~7;
    while (cursor < wordLimit) {
      // One input unit can emit at most one row. The available output capacity
      // bounds a safe input block, so the word loop needs no per-row growth check.
      fields = growLineFields(fields, field + 8 * BlockLineField.Stride);
      const wordEnd = Math.min(wordLimit, cursor + ((fields.length - field) / BlockLineField.Stride & ~7));
      let word0 = words[cursor >>> 2];
      let word1 = words[(cursor >>> 2) + 1];
      for (;;) {
        const mixed0 = word0 ^ (word0 & 0x01010101) * 7 ^ 0x0A0A0A0A;
        const mixed1 = word1 ^ (word1 & 0x01010101) * 7 ^ 0x0A0A0A0A;
        // Folding preserves the high bits; the even folded bytes make this mask exact.
        const hits0 = mixed0 - 0x01010101 & ~word0 & 0x80808080;
        const hits1 = mixed1 - 0x01010101 & ~word1 & 0x80808080;
        if ((hits0 | hits1) !== 0) {
          // A packed list stores ascending three-bit positions; zero can only be first.
          let events = positions[Math.imul((hits0 >>> 4) | hits1, 0x00204081) >>> 24];
          do {
            const at = cursor + (events & 7);
            const code = source.charCodeAt(at);
            // Latin1 copying retains low bytes, so exclude non-Latin1 aliases.
            if (code <= 0xFF) {
              let next = at + 1;
              if (code === Character.CarriageReturn) {
                lastCR = next;
                // Consume an adjacent LF in this block; cross-block LF uses the carry below.
                if (((events >>> 3) & 7) === (at & 7) + 1 && source.charCodeAt(next) === Character.LineFeed) {
                  next++;
                  events >>>= 3;
                }
              }
              else if (at === lastCR) {
                fields[field - 2] = next;
                start = next;
                continue;
              }
              // Four fields per row fit in 31 bits under Node's string length limit.
              fields[field] = start;
              fields[field | 1] = at;
              fields[field | 2] = next;
              fields[field | 3] = 0;
              field = (field + 4) & 0x7FFFFFFF;
              start = next;
            }
          } while ((events >>>= 3) !== 0);
        }
        cursor += 8;
        if (cursor >= wordEnd) {
          break;
        }
        word0 = words[cursor >>> 2];
        word1 = words[(cursor >>> 2) + 1];
      }
    }

    const tail = limit - cursor || (start < limit ? 1 : 0);
    fields = growLineFields(fields, field + tail * BlockLineField.Stride);
    for (; cursor < limit; cursor++) {
      const code = source.charCodeAt(cursor);
      if (code !== Character.CarriageReturn && code !== Character.LineFeed) {
        continue;
      }
      const next = cursor + 1;
      if (code === Character.CarriageReturn) {
        lastCR = next;
      }
      else if (cursor === lastCR) {
        fields[field - 2] = next;
        start = next;
        continue;
      }
      fields[field] = start;
      fields[field | 1] = cursor;
      fields[field | 2] = next;
      fields[field | 3] = 0;
      field = (field + 4) & 0x7FFFFFFF;
      start = next;
    }
    if (start < limit) {
      fields[field] = start;
      fields[field | 1] = limit;
      fields[field | 2] = limit;
      fields[field | 3] = 0;
      field = (field + 4) & 0x7FFFFFFF;
    }

    return {
      fields,
      length: field / BlockLineField.Stride,
      normalized: lastCR < 0,
    };
  }
}

class Index0 {
  static scan(source: string, fields: Int32Array): ScanningResult {
    let field = 0;
    let start = 0;
    let lf = source.indexOf("\n");
