      const available = (fields.length - field) / BlockLineField.Stride;
      const wordEnd = limit - cursor <= available ? wordLimit : cursor + (available & ~7);
      let word0 = words[cursor >>> 2];
      let word1 = words[(cursor >>> 2) + 1];
