];
function source(n,width,unicode,ending){const chars=unicode?'中文é😀\u010a\u010d':'abcdefghijklmnop';const row=chars.repeat(Math.ceil(width/chars.length)).slice(0,width);const pattern=ending===undefined?row+'\n'+row+'\r\n'+row+'\r':row+ending;return pattern.repeat(Math.ceil(n/pattern.length)).slice(0,n);}
function expected(s){let count=0,last=0;for(let i=0;i<s.length;i++){if(s.charCodeAt(i)===13){if(s.charCodeAt(i+1)===10)i++;count++;last=i+1;}else if(s.charCodeAt(i)===10){count++;last=i+1;}}return count+(last<s.length?1:0);}
const args=process.argv.slice(2);
if(args[0]==='--worker'){
 const {BlockLines}=await import(pathToFileURL(resolve(args[1])).href);const out={};let sink=0;
 for(const c of cases){
  const sources=c.sizes.map(n=>source(n,c.width,c.unicode,c.ending)),lines=new BlockLines();
  for(const s of sources){lines.scan(s);assert.equal(lines.length,expected(s));assert.equal(lines.next(lines.length-1),s.length);}
  const run=()=>{for(const s of sources){lines.scan(s);sink^=lines.length+lines.next(lines.length-1);}};
