 for(let block=0;block<4;block++)for(const variant of (block%2?'BAAB':'ABBA')){
  process.stderr.write(`scan ${block+1}/4 ${variant}\n`);
  const r=spawnSync(process.execPath,['--expose-gc',import.meta.filename,'--worker',variant==='A'?a:b],{encoding:'utf8',timeout:30000,maxBuffer:8*1024*1024});assert.equal(r.status,0,r.stderr);
  for(const [name,sample] of Object.entries(JSON.parse(r.stdout).out)){(report.results[name]??={runs:[]}).runs.push({variant,...sample});}
  writeFileSync(output,JSON.stringify(report,null,2));
 }
 for(const r of Object.values(report.results))r.summary=analyzeBlocks(r.runs);
 assert.deepEqual(hashes(),report.inputs);report.status='complete';writeFileSync(output,JSON.stringify(report,null,2));
 console.log(JSON.stringify(Object.fromEntries(Object.entries(report.results).map(([n,r])=>[n,r.summary])),null,2));
}

