export function trimLineWhitespaceStart(source: string, start: number, end: number): number {
  while (start < end) {
    const code = source.charCodeAt(start);
    if (code !== Character.Space && code !== Character.CharacterTabulation) {
      break;
    }
    start++;
  }
  return start;
}

