        fields = growLineFields(fields, field + BlockLineField.Stride);
      }
      fields[field++] = start;
      fields[field++] = end;
      fields[field++] = next;
      fields[field++] = 0;
      start = next;
    }

    return {
      fields,
      length: field / BlockLineField.Stride,
      normalized,
    };
  }
